import csv as _csv
import gc as _gc
import io as _io
import re as _re
import time as _time
import random as _random

_SHEET_ID  = "1lSoeoHXI_0FQga-64ekIDcVwRv56ykq8egcLNUSp8R4"
_SHEET_GID = "927689016"
_SHEET_URL = (
    f"https://docs.google.com/spreadsheets/d/{_SHEET_ID}"
    f"/gviz/tq?tqx=out:csv&gid={_SHEET_GID}"
)

_products_cache: list = []
_products_fetched: float = 0.0
_PRODUCTS_TTL: int = 3600  # 1 hour (was 10 min)  # 10 minutes

_COL_URL   = 4
_COL_TITLE = 5
_COL_CATS  = 26
_COL_TAGS  = 27
_COL_IMGS  = 33


def _title_to_slug(t: str) -> str:
    t = t.lower()
    t = _re.sub(r"\s*\|\s*", "-", t)
    t = _re.sub(r"[^a-z0-9-]", "-", t)
    t = _re.sub(r"-+", "-", t)
    return t.strip("-")


def _extract_slug(raw_url: str, title: str) -> str:
    s = (raw_url or "").strip()
    m = _re.search(r"/shop/p/([^/?#\s]+)", s)
    if m:
        return m.group(1)
    if s and _re.match(r"^[a-z0-9]", s) and " " not in s:
        return s
    return _title_to_slug(title)


def _tag_key(value: str) -> str:
    return _re.sub(r"[^a-z0-9]", "", (value or "").lower())


def _split_product_title(title: str, cats: str = "", tag_str: str = "") -> tuple:
    parts = [p.strip() for p in title.split("|") if p.strip()]
    if len(parts) >= 3:
        tag_keys = {_tag_key(t) for t in _re.split(r"[,，;；|｜/\\]+", cats + "," + tag_str) if t.strip()}
        first_key = _tag_key(parts[0])
        if first_key and first_key in tag_keys:
            return parts[0], parts[1]
    if len(parts) > 1:
        return parts[-1], "|".join(parts[:-1]).strip()
    return "", title


def _extract_artist(title: str) -> str:
    artist, _ = _split_product_title(title)
    return artist


def _parse_tags(cats: str, tag_str: str, artist: str) -> list:
    combined = cats + "," + tag_str
    tags = [t.strip().lower() for t in _re.split(r"[,ÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂ¯ÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂ¼ÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂ;ÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂ¯ÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂ¼ÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂ|ÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂ¯ÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂ½ÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂ/\\]+", combined) if t.strip()]
    if artist:
        tags.append(_re.sub(r"\s+", "", artist.lower()))
    return list(dict.fromkeys(tags))


async def _load_products() -> list:
    global _products_cache, _products_fetched
    now = _time.time()
    if _products_cache and now - _products_fetched < _PRODUCTS_TTL:
        return _products_cache

    import httpx as _httpx
    async with _httpx.AsyncClient(timeout=15) as client:
        resp = await client.get(_SHEET_URL)
        resp.raise_for_status()

    reader = _csv.reader(_io.StringIO(resp.text))
    rows = list(reader)
    if len(rows) < 2:
        raise ValueError("Spreadsheet appears to be empty.")

    seen: set = set()
    products: list = []
    for row in rows[1:]:
        if len(row) <= _COL_TITLE:
            continue
        title = row[_COL_TITLE].strip()
        if not title:
            continue
        raw_url = row[_COL_URL].strip() if len(row) > _COL_URL else ""
        slug = _extract_slug(raw_url, title)
        if not slug or slug in seen:
            continue
        seen.add(slug)

        cats      = row[_COL_CATS] if len(row) > _COL_CATS else ""
        tag_str   = row[_COL_TAGS] if len(row) > _COL_TAGS else ""
        artist, art_title = _split_product_title(title, cats, tag_str)
        tags      = _parse_tags(cats, tag_str, artist)
        imgs_cell = row[_COL_IMGS] if len(row) > _COL_IMGS else ""
        image     = imgs_cell.strip().split()[0] if imgs_cell.strip() else ""

        products.append({
            "title": title, "artTitle": art_title, "artist": artist,
            "slug": slug, "tags": tags, "image": image,
        })

    _products_cache = products
    _products_fetched = now
    _gc.collect()  # return fragmented heap memory
    try:
        import ctypes; ctypes.CDLL("libc.so.6").malloc_trim(0)
    except Exception:
        pass
    return products


def _recommend(products: list, current_slug: str, limit: int = 4) -> dict:
    current = next((p for p in products if p["slug"] == current_slug), None)
    if not current:
        return {"byArtist": [], "byTag": []}

    # Tags to skip for byTag section (layout/orientation tags, not meaningful for discovery)
    _SKIP_TAGS = {"horizontal", "vertical", "square"}

    # ÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂ Section 1: random works by the same artist ÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂ
    same_artist = [p for p in products
                   if p["slug"] != current_slug and p["artist"] == current["artist"]]
    _random.shuffle(same_artist)
    by_artist = same_artist[:limit]

    # ÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂ Section 2: one random work per tag, diverse artists ÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂÃÂ¢ÃÂÃÂ
    used_slugs = {current_slug} | {p["slug"] for p in by_artist}
    seen_artists: set = set()
    by_tag: list = []

    tags_shuffled = [t for t in current["tags"] if t not in _SKIP_TAGS]
    _random.shuffle(tags_shuffled)

    for tag in tags_shuffled:
        cur_artist_lower = current["artist"].strip().lower()
        candidates = [
            p for p in products
            if p["slug"] not in used_slugs
            and p["artist"].strip().lower() != cur_artist_lower
            and p["artist"].strip().lower() not in {a.lower() for a in seen_artists}
            and tag in p["tags"]
        ]
        if candidates:
            pick = _random.choice(candidates)
            by_tag.append(pick)
            used_slugs.add(pick["slug"])
            seen_artists.add(pick["artist"])
        if len(by_tag) >= limit:
            break

    # Pad with random works (still excluding same artist and already-seen artists)
    if len(by_tag) < limit:
        rest = [
            p for p in products
            if p["slug"] not in used_slugs
            and p["artist"] != current["artist"]
            and p["artist"] not in seen_artists
        ]
        _random.shuffle(rest)
        by_tag.extend(rest[:limit - len(by_tag)])

    def _fmt(p):
        return {
            "title":    p["title"],
            "artTitle": p["artTitle"],
            "artist":   p["artist"],
            "slug":     p["slug"],
            "url":      f"https://www.lightoarts.com/shop/p/{p['slug']}",
            "image":    p["image"],
        }

    return {
        "byArtist": [_fmt(p) for p in by_artist],
        "byTag":    [_fmt(p) for p in by_tag],
    }


