async def recommendations(
    slug: str = Query(..., description="Product slug"),
    limit: int = Query(4, ge=1, le=12),
):
    products = await _load_products()
    recs = _recommend(products, slug.lower().strip(), limit)
    return JSONResponse(recs)


@app.get("/random")
async def random_products(limit: int = Query(8, ge=1, le=24)):
    """Return N random products for non-product pages."""
    products = await _load_products()
    sample = _random.sample(products, min(limit, len(products)))
    return JSONResponse([{
        "title":    p["title"],
        "artTitle": p["artTitle"],
        "artist":   p["artist"],
        "slug":     p["slug"],
        "url":      f"https://www.lightoarts.com/shop/p/{p['slug']}",
        "image":    p["image"],
    } for p in sample])


@app.get("/products-list")
async def products_list():
    """Debug: full product catalogue with tags."""
    products = await _load_products()
    return JSONResponse(products)
